CustomField.formula:
ROUND(
    IF(
        CONTAINS(Experience__c, "years"),
        VALUE(
            TRIM(
                LEFT(
                    Experience__c, 
                    FIND("years", Experience__c) - 1
                )
            )
        ) +
        IF(
            CONTAINS(Experience__c, "months"),
            VALUE(
                TRIM(
                    MID(
                        Experience__c,
                        FIND("years", Experience__c) + 6,
                        FIND("months", Experience__c) - (FIND("years", Experience__c) + 6)
                    )
                )
            ) / 12,
            0
        ),
        IF(
            CONTAINS(Experience__c, "months"),
            VALUE(
                TRIM(
                    LEFT(
                        Experience__c,
                        FIND("months", Experience__c) - 1
                    )
                )
            ) / 12,
            0
        )
    ),
    2
)
